findings.codeql_raw_query:
/**
 * @name Improper modification of object attributes
 * @description Modifying object attributes with user-controlled input can lead to unexpected behavior.
 * @kind path-problem
 * @problem.severity warning
 * @id py/improper-attribute-modification
 * @tags security
 *       external/cwe/cwe-915
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module AttributeModificationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("setattr").getACall() and
      sink = call.getArg(1)
    )
  }
}

module AttributeModificationFlow = TaintTracking::Global<AttributeModificationConfig>;
import AttributeModificationFlow::PathGraph

from AttributeModificationFlow::PathNode source, AttributeModificationFlow::PathNode sink
where AttributeModificationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Attribute name controlled by user input from $@.", source.getNode(), "user input"
